{
  "sentences": [
    {
      "en": "Industrial voice control is limited by noisy environments that degrade audio-only speech recognition.",
      "es": "El control por voz en entornos industriales se limita por ruidos que degradan la reconocimiento de voz solo con audio.",
      "sources": [0]
    },
